begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.entitlements(school_id,code,enabled,effective_from)select id,'school.operations',true,'2026-09-01'from app.schools on conflict(school_id,code)do update set enabled=true;
insert into app.school_policy_versions(school_id,version,reason,approved_by)select'10000000-0000-4000-8000-000000000001',coalesce(max(version),0)+1,'SQL fixture conservative policy','20000000-0000-4000-8000-000000000001'from app.school_policy_versions where school_id='10000000-0000-4000-8000-000000000001';
select ok(to_regclass('app.attendance_revisions')is not null,'attendance revisions persist independently');
select ok(to_regclass('app.school_policy_versions')is not null,'school approvals versioned');
create temporary table school_ids(year_id uuid,term_id uuid,group_id uuid,class_id uuid,subject_id uuid,attendance_id uuid);grant select,insert,update on school_ids to cuevo_api;
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
insert into school_ids(year_id)select(internal.school_command('year.create',null,'{"name":"Technical Year","startsOn":"2026-09-01","endsOn":"2027-07-01"}','school-year-create-0001',repeat('a',64),'school-request')->>'id')::uuid;
select is((internal.school_command('year.create',null,'{"name":"Technical Year","startsOn":"2026-09-01","endsOn":"2027-07-01"}','school-year-create-0001',repeat('a',64),'school-replay')->>'id')::uuid,(select year_id from school_ids),'same key school creation replays once');
select throws_ok($$select internal.school_command('year.create',null,'{"name":"Changed","startsOn":"2026-09-01","endsOn":"2027-07-01"}','school-year-create-0001',repeat('b',64),'school-request')$$,'22023',null,'changed key payload conflicts');
update school_ids set term_id=(internal.school_command('term.create',null,jsonb_build_object('academicYearId',year_id,'name','Term','startsOn','2026-09-01','endsOn','2026-12-31'),'school-term-create-0001',repeat('b',64),'school-request')->>'id')::uuid;
select throws_ok($$select internal.school_command('term.create',null,jsonb_build_object('academicYearId',(select year_id from school_ids),'name','Invalid','startsOn','2025-09-01','endsOn','2026-12-31'),'school-term-outside-0001',repeat('c',64),'school-request')$$,'22023',null,'term dates cannot escape academic year');
select throws_ok($$select internal.school_command('person.configure','20000000-0000-4000-8000-000000000133','{"displayName":"Foreign","role":"student","status":"active","effectiveFrom":"2026-09-01T00:00:00Z","effectiveTo":null,"confirmAccessChange":true}','school-foreign-person-0001',repeat('d',64),'school-request')$$,'42501',null,'foreign Auth user cannot be attached to this tenant');
select throws_ok($$select internal.school_command('person.configure','99999999-0000-4000-8000-000000000001','{"displayName":"Unknown","role":"student","status":"active","effectiveFrom":"2026-09-01T00:00:00Z","effectiveTo":null,"confirmAccessChange":true}','school-unknown-person-0001',repeat('d',64),'school-request')$$,'42501',null,'unprovisioned identity cannot become membership');
select throws_ok($$select internal.school_command('person.configure','20000000-0000-4000-8000-000000000001','{"displayName":"Admin","role":"student","status":"active","effectiveFrom":"2026-09-01T00:00:00Z","effectiveTo":null,"confirmAccessChange":true}','school-admin-remove-0001',repeat('e',64),'school-request')$$,'22023',null,'admin cannot remove own current access');
select throws_ok($$select internal.school_command('guardian.configure',null,'{"parentId":"20000000-0000-4000-8000-000000000072","studentId":"20000000-0000-4000-8000-000000000012","relationshipType":"parent","status":"active","effectiveFrom":"2026-09-01T00:00:00Z","effectiveTo":null}','school-guardian-confirm-0001',repeat('f',64),'school-request')$$,'22023',null,'human confirmation required for relationship');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.school_command('year.create',null,'{"name":"Teacher denied","startsOn":"2026-09-01","endsOn":"2027-07-01"}','school-teacher-year-0001',repeat('a',64),'school-request')$$,'42501',null,'teacher cannot configure school setup');
update school_ids set attendance_id=(internal.school_command('attendance.record',null,'{"classId":"30000000-0000-4000-8000-000000000001","studentId":"20000000-0000-4000-8000-000000000012","occurredOn":"2026-10-01","status":"present","note":"Teacher observed","expectedRevision":0}','school-attendance-first-0001',repeat('a',64),'school-request')->>'id')::uuid;
select throws_ok($$select internal.school_command('attendance.record',null,'{"classId":"30000000-0000-4000-8000-000000000001","studentId":"20000000-0000-4000-8000-000000000012","occurredOn":"2026-10-01","status":"absent","note":"","expectedRevision":0}','school-attendance-stale-0001',repeat('b',64),'school-request')$$,'22023',null,'stale attendance revision rejected');
reset role;
update app.memberships set effective_to=now()-interval'1 day'where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select throws_ok($$select internal.school_command('attendance.record',null,'{"classId":"30000000-0000-4000-8000-000000000001","studentId":"20000000-0000-4000-8000-000000000012","occurredOn":"2026-10-01","status":"present","note":"Teacher observed","expectedRevision":0}','school-attendance-first-0001',repeat('a',64),'school-expired-replay')$$,'42501',null,'admin cannot replay attendance for expired learner membership');
select throws_ok($$select internal.school_command('attendance.record',null,'{"classId":"30000000-0000-4000-8000-000000000001","studentId":"20000000-0000-4000-8000-000000000012","occurredOn":"2026-10-03","status":"present","note":"","expectedRevision":0}','school-expired-attendance-0001',repeat('b',64),'school-request')$$,'42501',null,'admin cannot record new attendance for expired learner membership');
reset role;update app.memberships set effective_from=now()+interval'1 day',effective_to=null where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select throws_ok($$select internal.school_command('attendance.record',null,'{"classId":"30000000-0000-4000-8000-000000000001","studentId":"20000000-0000-4000-8000-000000000012","occurredOn":"2026-10-03","status":"present","note":"","expectedRevision":0}','school-future-attendance-0001',repeat('b',64),'school-request')$$,'42501',null,'admin cannot record attendance for future learner membership');
reset role;update app.memberships set effective_from='2026-09-01',effective_to=null where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is(jsonb_array_length(internal.school_list('attendance','{"limit":25}')->'items'),0,'parent attendance closed by default');
select throws_ok($$select internal.school_list('people','{"limit":25}')$$,'42501',null,'parent cannot enumerate school identities');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select lives_ok($$select internal.school_command('policy.approve',null,jsonb_build_object('expectedVersion',(select max(version)from app.school_policy_versions),'parentAttendanceVisible',true,'parentUpcomingVisible',true,'studentMessagingEnabled',false,'recognitionEnabled',false,'leaderboardEnabled',false,'analyticsEnabled',false,'reason','Admin approved child projection','confirmPolicyApproval',true),'school-policy-first-0001',repeat('c',64),'school-request')$$,'explicit admin approval opens minimum parent projection');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select ok(exists(select 1 from jsonb_array_elements(internal.school_list('attendance','{"limit":100}')->'items')item where item->>'id'=(select attendance_id::text from school_ids)),'current guardian can read approved child attendance');
select ok((select item->'note'='null'::jsonb from jsonb_array_elements(internal.school_list('attendance','{"limit":100}')->'items')item where item->>'id'=(select attendance_id::text from school_ids)),'parent does not receive staff attendance note');
reset role;update app.parent_relationships set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and parent_actor_id='20000000-0000-4000-8000-000000000072';
set local role cuevo_api;
select is(jsonb_array_length(internal.school_list('attendance','{"limit":25}')->'items'),0,'revoked guardian has no new attendance access');
reset role;
select throws_ok($$update app.attendance_revisions set status='absent'where id=(select attendance_id from school_ids)$$,'55000',null,'attendance history cannot be overwritten');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.rolname in('anon','authenticated','service_role','cuevo_worker')where n.nspname='app'and c.relname in('attendance_revisions','school_policy_versions','timetable_entries','calendar_events','report_periods')and has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE')),'school ops private from browser Data API worker');
select *from finish();rollback;
